import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.BCZ_EjGL.js";const g=JSON.parse('{"title":"Bot Training for 100% Accuracy","description":"","frontmatter":{},"headers":[],"relativePath":"v1.0.0/training.md","filePath":"v1.0.0/training.md"}'),i={name:"v1.0.0/training.md"};function s(n,e,l,u,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="bot-training-for-100-accuracy" tabindex="-1">Bot Training for 100% Accuracy <a class="header-anchor" href="#bot-training-for-100-accuracy" aria-label="Permalink to &quot;Bot Training for 100% Accuracy&quot;">​</a></h1><p>To achieve maximum accuracy with AskBot AI, the quality of your Q&amp;A pairs is key. This guide outlines the best practices for &quot;training&quot; your bot to understand user intent perfectly.</p><h2 id="the-question-field-keywords" tabindex="-1">The &quot;Question&quot; Field (Keywords) <a class="header-anchor" href="#the-question-field-keywords" aria-label="Permalink to &quot;The &quot;Question&quot; Field (Keywords)&quot;">​</a></h2><p>The <code>question</code> field in AskBot AI is not just for a single question. It acts as a set of <strong>triggers</strong>. You should include multiple variations separated by commas.</p><hr><h2 id="do-s-✅" tabindex="-1">Do&#39;s ✅ <a class="header-anchor" href="#do-s-✅" aria-label="Permalink to &quot;Do&#39;s ✅&quot;">​</a></h2><h3 id="_1-use-natural-language-variations" tabindex="-1">1. Use Natural Language Variations <a class="header-anchor" href="#_1-use-natural-language-variations" aria-label="Permalink to &quot;1. Use Natural Language Variations&quot;">​</a></h3><p>Users ask the same thing in multiple ways. Include common variations to improve matching.</p><ul><li><strong>Example:</strong> <code>question: &quot;sales report, show sales, open sales dashboard, revenue data&quot;</code></li></ul><h3 id="_2-keep-answers-concise-and-direct" tabindex="-1">2. Keep Answers Concise and Direct <a class="header-anchor" href="#_2-keep-answers-concise-and-direct" aria-label="Permalink to &quot;2. Keep Answers Concise and Direct&quot;">​</a></h3><p>Direct answers are easier for users to digest. Use Markdown to structure longer responses.</p><ul><li><strong>Example:</strong> <code>answer: &quot;The Q3 revenue was **$2.4M**, showing a **12% growth** YoY.&quot;</code></li></ul><h3 id="_3-use-specific-keywords" tabindex="-1">3. Use Specific Keywords <a class="header-anchor" href="#_3-use-specific-keywords" aria-label="Permalink to &quot;3. Use Specific Keywords&quot;">​</a></h3><p>Include terms users are likely to search for (e.g., product names, department names).</p><ul><li><strong>Example:</strong> <code>question: &quot;HR policy, vacation policy, leave request details&quot;</code></li></ul><h3 id="_4-provide-contextual-buttons" tabindex="-1">4. Provide Contextual Buttons <a class="header-anchor" href="#_4-provide-contextual-buttons" aria-label="Permalink to &quot;4. Provide Contextual Buttons&quot;">​</a></h3><p>Use <code>actions</code> to guide the user to the next step, reducing the need for them to type again.</p><ul><li><strong>Example:</strong> Add a &quot;Request Leave&quot; button to a vacation policy answer.</li></ul><hr><h2 id="don-ts-❌" tabindex="-1">Don&#39;ts ❌ <a class="header-anchor" href="#don-ts-❌" aria-label="Permalink to &quot;Don&#39;ts ❌&quot;">​</a></h2><h3 id="_1-avoid-ambiguous-triggers" tabindex="-1">1. Avoid Ambiguous Triggers <a class="header-anchor" href="#_1-avoid-ambiguous-triggers" aria-label="Permalink to &quot;1. Avoid Ambiguous Triggers&quot;">​</a></h3><p>Vague keywords lead to incorrect matches or confusion.</p><ul><li><strong>Bad Example:</strong> <code>question: &quot;status, info, data&quot;</code></li><li><strong>Better:</strong> <code>question: &quot;project status, system info, sales data&quot;</code></li></ul><h3 id="_2-avoid-overly-technical-jargon" tabindex="-1">2. Avoid Overly Technical Jargon <a class="header-anchor" href="#_2-avoid-overly-technical-jargon" aria-label="Permalink to &quot;2. Avoid Overly Technical Jargon&quot;">​</a></h3><p>Unless your audience is technical, use simple language in both questions and answers.</p><ul><li><strong>Avoid:</strong> &quot;Execute the SQL query on the normalized schema.&quot;</li><li><strong>Use:</strong> &quot;Run the search on the main data table.&quot;</li></ul><h3 id="_3-don-t-duplicate-intent" tabindex="-1">3. Don&#39;t Duplicate Intent <a class="header-anchor" href="#_3-don-t-duplicate-intent" aria-label="Permalink to &quot;3. Don&#39;t Duplicate Intent&quot;">​</a></h3><p>If two Q&amp;A pairs have identical keywords but different answers, the bot may return the wrong one. Ensure each pair has a unique set of triggers.</p><h3 id="_4-avoid-single-broad-words" tabindex="-1">4. Avoid Single Broad Words <a class="header-anchor" href="#_4-avoid-single-broad-words" aria-label="Permalink to &quot;4. Avoid Single Broad Words&quot;">​</a></h3><p>Single words like &quot;Help&quot; or &quot;How&quot; are too broad. Combine them with a subject.</p><ul><li><strong>Better:</strong> &quot;Help with login&quot;, &quot;How to export data&quot;.</li></ul><hr><h2 id="quick-reference-table" tabindex="-1">Quick Reference Table <a class="header-anchor" href="#quick-reference-table" aria-label="Permalink to &quot;Quick Reference Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Best Practice</th><th style="text-align:left;">Example</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Accuracy</strong></td><td style="text-align:left;">Use specific, unambiguous triggers.</td><td style="text-align:left;">&quot;What is the budget for 2024?&quot;</td></tr><tr><td style="text-align:left;"><strong>User Experience</strong></td><td style="text-align:left;">Use Markdown for readability.</td><td style="text-align:left;">&quot;<strong>Bold</strong> key figures.&quot;</td></tr><tr><td style="text-align:left;"><strong>Efficiency</strong></td><td style="text-align:left;">Use comma-separated variations.</td><td style="text-align:left;">&quot;Help, support, contact&quot;</td></tr></tbody></table><p>By following these simple rules, you can ensure your bot provides the right answer <strong>100% of the time</strong>.</p>',35)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
